syntax:
for (int i = 1; i <= rows; i++)          // outer loop: rows
{
    for (int j = 1; j <= cols; j++)      // inner loop: columns
    {
        // inner body: runs rows x cols times
        cout << i * j << "\t";
    }
    cout << endl;                        // after the inner loop: next row
}

sample.code:
#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 2; i++) {
        for (int j = 1; j <= 3; j++) {
            cout << "(" << i << "," << j << ") ";
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int count = 0;
    for (int i = 1; i <= 4; i++) {
        for (int j = 1; j <= 5; j++) {
            cout << i * j << "\t";
            count++;
        }
        cout << endl;
    }
    cout << "Inner body ran " << count << " times" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int count = 0;
    for (int i = 1; i <= 4; i++) {
        for (int j = 1; j <= i; j++) {
            cout << "*";
            count++;
        }
        cout << endl;
    }
    cout << "Total stars = " << count << endl;
    return 0;
}

